mapper.select:
SELECT  FROM light_user_roles
WHERE deleted_at IS NULL AND user_id = #{userId}
ORDER BY id

mapper.update:
UPDATE light_user_roles SET deleted_at=(CURRENT_TIMESTAMP AT TIME ZONE 'UTC'), version=version+1,
    update_user_id=#{et.updateUserId}, update_time=#{et.updateTime}
WHERE id=#{et.id} AND tenant_id=#{et.tenantId} AND deleted_at IS NULL AND version=#{MP_OPTLOCK_VERSION_ORIGINAL}
